call.content:
{
  "schema_version": "1.0.0",
  "action": "answer",
  "response": null,
  "claims": [
    {
      "id": "c1",
      "text": "The Vbot Model Gateway implements a failover ladder with retry, cooldown, and model-level fallback.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c2",
      "text": "The primary RP model is single-host on OpenRouter, so a hot-standby model is the second rung.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c3",
      "text": "The model lab stays on direct OpenRouter with no fallback to prevent silent model swapping and poisoning of blind ratings.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c4",
      "text": "The gateway is a product concern, not a lab concern.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c5",
      "text": "The Vbot Model Gateway has a provisioned Prometheus + Grafana setup for monitoring and configuration management.",
      "citation_ids": ["S2"]
    },
    {
      "id": "c6",
      "text": "The gateway has a circuit breaker that trips during cooldown, and the deployment state is visible in the dashboard.",
      "citation_ids": ["S5"]
    },
    {
      "id": "c7",
      "text": "The gateway has a budget-capped virtual key system for per-key spend tracking and abuse prevention.",
      "citation_ids": ["S3"]
    }
  ]
}

